#include <deque>
#include <vector>
#include <map>
struct Resting { long long id; long long size; };
struct Trade { long long restingId; double price; long long size; };
// asks: price -> FIFO queue of resting orders (std::map keeps ascending order)
std::vector<Trade> matchBuy(std::map<double, std::deque<Resting>>& asks,
                            double limitPrice, long long qty){
    std::vector<Trade> trades;
    while (qty > 0 && !asks.empty()){
        auto it = asks.begin();           // best (lowest) ask
        if (it->first > limitPrice) break; // no longer crosses
        auto& queue = it->second;
        while (qty > 0 && !queue.empty()){
            Resting& front = queue.front();
            long long fill = std::min(qty, front.size);
            trades.push_back({front.id, it->first, fill});
            front.size -= fill; qty -= fill;
            if (front.size == 0) queue.pop_front();
        }
        if (queue.empty()) asks.erase(it);
    }
    return trades; // remaining qty (if any) would rest as a new bid
}

from collections import deque

def match_buy(asks, limit_price, qty):
    # asks: dict price -> deque of [id, size]; we sort keys for best-first
    trades = []
    for price in sorted(asks):
        if qty <= 0 or price > limit_price:
            break
        q = asks[price]
        while qty > 0 and q:
            front = q[0]
            fill = min(qty, front[1])
            trades.append((front[0], price, fill))
            front[1] -= fill
            qty -= fill
            if front[1] == 0:
                q.popleft()
        if not q:
            del asks[price]
    return trades  # leftover qty would rest as a new bid
